-- RMIMS DEMO DATA SEED
-- THESIS-ALIGNED DEMO/TEST DATA ONLY.
-- Product/raw-material names follow the uploaded thesis.
-- Quantities, suppliers, stock levels, recipes, and historical usage values are synthetic sample data created for system testing.
-- Do not present these generated quantities as actual business records.
BEGIN;

-- Clean existing demo/draft records safely to prevent name constraint collisions
DELETE FROM public.product_material_requirements;
DELETE FROM public.finished_products;

ON CONFLICT (id) DO UPDATE SET material_name=EXCLUDED.material_name, category=EXCLUDED.category, unit=EXCLUDED.unit, quantity=EXCLUDED.quantity, minimum_threshold=EXCLUDED.minimum_threshold, supplier=EXCLUDED.supplier, storage_location=EXCLUDED.storage_location, notes=EXCLUDED.notes, status=EXCLUDED.status;


ON CONFLICT (product_id, material_id) DO UPDATE SET required_quantity=EXCLUDED.required_quantity, unit=EXCLUDED.unit;

-- Remove only rows previously generated by this demo seed, then rebuild them.
DELETE FROM public.usage_records
WHERE remarks = 'RMIMS DEMO HISTORICAL CONSUMPTION'
  AND usage_date BETWEEN '2023-01-01' AND '2026-07-26';

ON CONFLICT (id) DO NOTHING;

COMMIT;
